        for (let i = 0; i < phnum; i++) {
            const off = phoff + i * phent;
            const type = view.getUint32(off, true);
            if (type === 1) { // PT_LOAD
                const fileOff = view.getUint32(off + 4, true);
                const vaddr = view.getUint32(off + 12, true);
                const filesz = view.getUint32(off + 24, true);
                const memsz = view.getUint32(off + 28, true);
                const flags = view.getUint32(off + 8, true);

                const src = new Uint8Array(buffer, fileOff, filesz);
                const dst = new Uint8Array(this.memory, vaddr, filesz);
                dst.set(src);

                for (let j = filesz; j < memsz; j++) {
                    this.memory[vaddr + j] = 0;
                }
            }
        }
    }

    readU32(addr) {
        return new DataView(this.memory).getUint32(addr, true);
    }

    writeU32(addr, val) {
        new DataView(this.memory).setUint32(addr, val >>> 0, true);
    }

    signExtend(val, bits) {
