                case 0x21: this.reg[rd] = (this.reg[rs] + this.reg[rt]) | 0; this.pc += 4; break; // ADDU
                case 0x0C: this.reg[rd] = this.reg[rs] & this.reg[rt]; this.pc += 4; break; // AND
                case 0x0A: this.reg[rd] = this.reg[rs] | this.reg[rt]; this.pc += 4; break; // OR
                case 0x0F: this.reg[rd] = ((this.reg[rs]|0) < (this.reg[rt]|0)) ? 1 : 0; this.pc += 4; break; // SLT
                case 0x03: this.pc = this.reg[rs] | 0; break; // JR
                case 0x01: this.reg[31] = this.pc + 4; this.pc = this.reg[rs] | 0; break; // JALR
