                    break;
                default: this.pc += 4; break;
            }
        } else {
            const rs = (instr >>> 21) & 0x1F;
            const rt = (instr >>> 16) & 0x1F;
            const imm = this.signExtend(instr & 0xFFFF, 16);

            switch (op) {
                case 0x08: this.reg[rt] = ((this.reg[rs]|0) + imm) | 0; this.pc += 4; break; // ADDI
                case 0x09: this.reg[rt] = ((this.reg[rs]|0) + imm) | 0; this.pc += 4; break; // ADDIU
