    }

    readI32(addr) {
        return new DataView(this.memory).getInt32(addr, true);
    }

    async run(maxSteps = 10000000) {
        for (let i = 0; i < maxSteps; i++) {
            if (this.pc < 0x400000 || this.pc > 0x40000000) {
                console.log('PC out of range:', '0x' + this.pc.toString(16));
